@Control Curadoria as "Curadoria do acervo"
@Database Catálogo
@Starter(Pesquisadora)
Pesquisadora -> Curadoria.revisarEvidência("EV-42") {
  Catálogo.buscarReferências("memória urbana")
  return "parecer disponível"
}

